public class RekeningBank {
    private BigDecimal saldo;          // private = tidak bisa diakses langsung dari luar

    public RekeningBank(BigDecimal saldoAwal) {
        this.saldo = saldoAwal;
    }

    public void setor(BigDecimal jumlah) {
        if (jumlah.compareTo(BigDecimal.ZERO) <= 0)
            throw new IllegalArgumentException("Jumlah harus positif");
        this.saldo = this.saldo.add(jumlah);
    }

    public BigDecimal getSaldo() { return saldo; }   // getter terkontrol
}

public class RekeningTabungan extends RekeningBank {
    private BigDecimal sukuBunga;

    public RekeningTabungan(BigDecimal saldoAwal, BigDecimal sukuBunga) {
        super(saldoAwal);          // panggil konstruktor induk
        this.sukuBunga = sukuBunga;
    }
}

