    Map<Character, Integer> map = new HashMap<>();
    for (char c : s.toCharArray()) map.merge(c, 1, Integer::sum);
    for (char c : t.toCharArray()) {
        if (!map.containsKey(c)) return false;
        map.merge(c, -1, Integer::sum);
        if (map.get(c) == 0) map.remove(c);
