public int searchRotated(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) return mid;
        // Setengah kiri masih terurut
        if (nums[left] <= nums[mid]) {
            if (nums[left] <= target && target < nums[mid]) right = mid - 1;
            else left = mid + 1;
        } else {
            // Setengah kanan masih terurut
            if (nums[mid] < target && target <= nums[right]) left = mid + 1;
            else right = mid - 1;
        }
    }
    return -1;
}

public int findMinRotated(int[] nums) {
    int left = 0, right = nums.length - 1;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] > nums[right]) left = mid + 1;
        else right = mid;
    }
    return nums[left];
}

public int exponentialSearch(int[] arr, int target) {
    if (arr.length == 0) return -1;
    if (arr[0] == target) return 0;
    int i = 1;
    while (i < arr.length && arr[i] <= target) i *= 2;
    return binarySearchRecursive(arr, target, i / 2, Math.min(i, arr.length - 1));
}

public int mySqrt(int x) {
    if (x < 2) return x;
    long left = 1, right = x / 2;
    while (left <= right) {
        long mid = left + (right - left) / 2;
        if (mid * mid == x) return (int) mid;
        else if (mid * mid < x) left = mid + 1;
        else right = mid - 1;
    }
    return (int) right; // floor(sqrt(x))
}

public char nextGreatestLetter(char[] letters, char target) {
    int left = 0, right = letters.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (letters[mid] <= target) left = mid + 1;
        else right = mid - 1;
    }
    return letters[left % letters.length]; // % untuk wrap around
}

