public int guessNumber(int n) {
    int left = 1, right = n;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        int result = guess(mid);
        if (result == 0) return mid;
        else if (result == 1) left = mid + 1;
        else right = mid - 1;
    }
    return -1;
}

public boolean isPalindrome(String s) {
    s = s.replaceAll("[^a-zA-Z0-9]", "").toLowerCase();
    int left = 0, right = s.length() - 1;
    while (left < right) {
        if (s.charAt(left) != s.charAt(right)) return false;
        left++; right--;
    }
    return true;
}

// Variasi: Cek apakah bisa jadi palindrome dengan hapus SATU karakter
// Contoh: "abca" → true (hapus 'c' → "aba")
// LeetCode 680
public boolean validPalindromeDeletion(String s) {
    int left = 0, right = s.length() - 1;
    while (left < right) {
        if (s.charAt(left) != s.charAt(right)) {
            return isPalindromeRange(s, left + 1, right) ||
                   isPalindromeRange(s, left, right - 1);
        }
        left++; right--;
    }
    return true;
}

private boolean isPalindromeRange(String s, int left, int right) {
    while (left < right) {
        if (s.charAt(left) != s.charAt(right)) return false;
        left++; right--;
    }
    return true;
}

public int lengthOfLongestSubstring(String s) {
    int maxLength = 0, left = 0;
    Set<Character> set = new HashSet<>();
    for (int right = 0; right < s.length(); right++) {
        while (set.contains(s.charAt(right))) {
            set.remove(s.charAt(left));
            left++;
        }
        set.add(s.charAt(right));
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

// Variasi dengan HashMap: lebih efisien, tidak perlu loop remove
public int lengthOfLongestSubstringMap(String s) {
    Map<Character, Integer> lastSeen = new HashMap<>();
    int maxLength = 0, left = 0;
    for (int right = 0; right < s.length(); right++) {
        char c = s.charAt(right);
        if (lastSeen.containsKey(c) && lastSeen.get(c) >= left) {
            left = lastSeen.get(c) + 1; // Langsung loncat, tidak perlu loop
        }
        lastSeen.put(c, right);
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

public String longestPalindrome(String s) {
    if (s == null || s.length() < 1) return "";
    int start = 0, end = 0;
    for (int i = 0; i < s.length(); i++) {
        int len1 = expandAroundCenter(s, i, i);       // Panjang ganjil
        int len2 = expandAroundCenter(s, i, i + 1);  // Panjang genap
        int len = Math.max(len1, len2);
        if (len > end - start) {
            start = i - (len - 1) / 2;
            end = i + len / 2;
        }
    }
    return s.substring(start, end + 1);
}

private int expandAroundCenter(String s, int left, int right) {
    while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
        left--;
        right++;
    }
    return right - left - 1; // Panjang palindrome yang ditemukan
}

public int myAtoi(String s) {
    int i = 0, n = s.length();
    // 1. Lewati spasi awal
    while (i < n && s.charAt(i) == ' ') i++;
    if (i == n) return 0;
    // 2. Cek tanda
    int sign = 1;
    if (s.charAt(i) == '+') i++;
    else if (s.charAt(i) == '-') { sign = -1; i++; }
    // 3. Parse digit dan cek overflow
    long result = 0;
    while (i < n && Character.isDigit(s.charAt(i))) {
        result = result * 10 + (s.charAt(i) - '0');
        if (result * sign > Integer.MAX_VALUE) return Integer.MAX_VALUE;
        if (result * sign < Integer.MIN_VALUE) return Integer.MIN_VALUE;
        i++;
    }
    return (int)(result * sign);
}

public String countAndSay(int n) {
    if (n <= 0) return "";
    String result = "1";
    for (int i = 1; i < n; i++) {
        StringBuilder sb = new StringBuilder();
        int count = 1;
        for (int j = 1; j < result.length(); j++) {
            if (result.charAt(j) == result.charAt(j - 1)) count++;
            else {
                sb.append(count).append(result.charAt(j - 1));
                count = 1;
            }
        }
        sb.append(count).append(result.charAt(result.length() - 1));
        result = sb.toString();
    }
    return result;
}

public String reverseWords(String s) {
