private void fillLayer(char[][] grid, int layer, int size, int n) {
    if (layer >= n / 2) {
        if (n % 2 == 1) grid[n / 2][n / 2] = '*'; // Titik tengah
        return;
    }
    int last = n - 1 - layer;
    for (int i = layer; i <= last; i++) {
        grid[layer][i] = '*'; // Atas
        grid[last][i] = '*'; // Bawah
        grid[i][layer] = '*'; // Kiri
        grid[i][last] = '*'; // Kanan
    }
    fillLayer(grid, layer + 2, size, n); // Lewati satu layer agar terlihat kosong di antara
}

