public List<List<Integer>> permutations(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    permuteHelper(nums, 0, result);
    return result;
}

private void permuteHelper(int[] nums, int start, List<List<Integer>> result) {
    if (start == nums.length) {
        List<Integer> perm = new ArrayList<>();
        for (int num : nums) perm.add(num);
        result.add(perm);
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);                   // Pilih nums[i] sebagai posisi start
        permuteHelper(nums, start + 1, result);
        swap(nums, start, i);                   // Backtrack: kembalikan ke semula
    }
}

public List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    subsetsHelper(nums, 0, new ArrayList<>(), result);
    return result;
}

private void subsetsHelper(int[] nums, int idx, List<Integer> current, List<List<Integer>> result) {
    result.add(new ArrayList<>(current)); // Tambah snapshot current ke result
    for (int i = idx; i < nums.length; i++) {
        current.add(nums[i]);
        subsetsHelper(nums, i + 1, current, result);
        current.remove(current.size() - 1); // Backtrack
    }
}

public int solveNQueens(int n) {
    return nQueensHelper(new int[n], 0, n);
}

private int nQueensHelper(int[] queens, int row, int n) {
    if (row == n) return 1; // Semua baris terisi = 1 solusi valid
    int count = 0;
    for (int col = 0; col < n; col++) {
        if (isValidQueen(queens, row, col)) {
            queens[row] = col;
            count += nQueensHelper(queens, row + 1, n);
        }
    }
    return count;
}

private boolean isValidQueen(int[] queens, int row, int col) {
    for (int i = 0; i < row; i++) {
        if (queens[i] == col) return false; // Kolom sama
        if (Math.abs(queens[i] - col) == Math.abs(i - row)) return false; // Diagonal sama
    }
    return true;
}

public boolean wordBreak(String s, List<String> wordDict) {
    Set<String> dict = new HashSet<>(wordDict);
    boolean[] dp = new boolean[s.length() + 1];
    dp[0] = true; // String kosong selalu valid
    for (int i = 1; i <= s.length(); i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] && dict.contains(s.substring(j, i))) {
                dp[i] = true;
                break;
            }
        }
    }
    return dp[s.length()];
}

public List<List<Integer>> combinationSum(int[] candidates, int target) {
    List<List<Integer>> result = new ArrayList<>();
    Arrays.sort(candidates);
    combinationHelper(candidates, target, 0, new ArrayList<>(), result);
    return result;
}

private void combinationHelper(int[] candidates, int remain, int start,
                               List<Integer> current, List<List<Integer>> result) {
    if (remain == 0) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = start; i < candidates.length; i++) {
        if (candidates[i] > remain) break; // Tidak perlu lanjut (sudah terurut)
        current.add(candidates[i]);
        combinationHelper(candidates, remain - candidates[i], i, current, result); // i bukan i+1 karena boleh pakai lagi
        current.remove(current.size() - 1); // Backtrack
    }
}

public boolean canJump(int[] nums) {
    int maxReach = 0;
    for (int i = 0; i < nums.length; i++) {
        if (i > maxReach) return false; // Tidak bisa mencapai i
        maxReach = Math.max(maxReach, i + nums[i]);
    }
    return true;
}

// Variant: Minimum jumps to reach end — DP O(n)
// Contoh: [2,3,1,1,4] → 2 lompatan
// LeetCode 45
public int jumpMinSteps(int[] nums) {
    int jumps = 0, currentEnd = 0, farthest = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        farthest = Math.max(farthest, i + nums[i]);
        if (i == currentEnd) { // Harus lompat sekarang
            jumps++;
            currentEnd = farthest;
        }
    }
    return jumps;
}

private void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

package com.belajar.algorithms.recursion;

public class KadaneAlgorithm {
    // LeetCode 53 - Maximum Subarray
    static int maxSubArray(int[] nums) {
        int maxSum = nums[0];
        int curr = nums[0];

        for (int i = 1; i < nums.length; i++) {
            // Lanjutkan subarray atau mulai baru dari sini?
            curr = Math.max(nums[i], curr + nums[i]);
            maxSum = Math.max(maxSum, curr);
        }
        return maxSum;
    }

    public static void main(String[] args) {
        int[] nums = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
        System.out.println(maxSubArray(nums)); // 6 → [4,-1,2,1]
    }
}

package com.belajar.algorithms.recursion;

public class HouseRobber {

    // LeetCode 198 - House Robber (array biasa)
    static int rob(int[] nums) {
        if (nums.length == 1) return nums[0];
        int prev2 = 0, prev1 = 0;

        for (int num : nums) {
            int curr = Math.max(prev1, prev2 + num);
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }

    // LeetCode 213 - House Robber II (array melingkar)
    static int robCircular(int[] nums) {
        if (nums.length == 1) return nums[0];
        // Coba dua kali: skip rumah pertama atau skip rumah terakhir
        return Math.max(
            robRange(nums, 0, nums.length - 2),
            robRange(nums, 1, nums.length - 1)
        );
    }

    static int robRange(int[] nums, int lo, int hi) {
        int prev2 = 0, prev1 = 0;
        for (int i = lo; i <= hi; i++) {
            int curr = Math.max(prev1, prev2 + nums[i]);
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }

    public static void main(String[] args) {
        System.out.println(rob(new int[]{2,7,9,3,1}));         // 12
        System.out.println(robCircular(new int[]{2,3,2}));     // 3
    }
}

package com.belajar.algorithms.recursion;

import java.util.Arrays;

public class CoinChangeVariants {


    // Variant 1: Minimum koin (LeetCode 322)
    static int minCoins(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;

        for (int i = 1; i <= amount; i++) {
            for (int coin : coins) {
                if (coin <= i) {
                    dp[i] = Math.min(dp[i], dp[i - coin] + 1);
                }
            }
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }

    // Variant 2: Berapa banyak kombinasi? (LeetCode 518)
    static int countWays(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        dp[0] = 1; // 1 cara untuk amount = 0

        for (int coin : coins) {
            for (int i = coin; i <= amount; i++) {
                dp[i] += dp[i - coin];
            }
        }
        return dp[amount];
    }

    public static void main(String[] args) {
        int[] coins = {1, 5, 6, 9};
        System.out.println(minCoins(coins, 11));  // 2 → (5+6)
        System.out.println(countWays(coins, 11)); // 4 kombinasi
    }
}

package com.belajar.algorithms.recursion;

import java.util.Arrays;

public class KnapsackVariants {

    // Variant 1: Apakah bisa mencapai target? (LeetCode 416)
    static boolean canPartition(int[] nums) {
        int total = Arrays.stream(nums).sum();
        if (total % 2 != 0) return false;
        int target = total / 2;

        boolean[] dp = new boolean[target + 1];
        dp[0] = true;

        for (int num : nums) {
            // Iterasi mundur agar tiap item hanya dipakai sekali!
            for (int j = target; j >= num; j--) {
                dp[j] = dp[j] || dp[j - num];
            }
        }
        return dp[target];
    }

    // Variant 2: Target Sum berapa banyak cara (LeetCode 494)
    static int findTargetSumWays(int[] nums, int target) {
        int sum = Arrays.stream(nums).sum();
        // Rumus: P - N = target dan P + N = sum → P = (sum+target)/2
        if ((sum + target) % 2 != 0 || Math.abs(target) > sum) return 0;
        int newTarget = (sum + target) / 2;

        int[] dp = new int[newTarget + 1];
        dp[0] = 1;

        for (int num : nums) {
            for (int j = newTarget; j >= num; j--) {
                dp[j] += dp[j - num];
            }
        }
        return dp[newTarget];
    }

    public static void main(String[] args) {
        System.out.println(canPartition(new int[]{1,5,11,5}));       // true
        System.out.println(findTargetSumWays(new int[]{1,1,1,1,1}, 3)); // 5
    }
}

package com.belajar.algorithms.recursion;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class LongestIncreasingSubsequence {

    // LeetCode 300 - O(n²) versi mudah dipahami
    static int lisSimple(int[] nums) {
        int n = nums.length;
        int[] dp = new int[n];
        Arrays.fill(dp, 1); // minimum LIS tiap elemen = 1

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) {
                    dp[i] = Math.max(dp[i], dp[j] + 1);
                }
            }
        }

        int max = 1;
        for (int val : dp) max = Math.max(max, val);
        return max;
    }

    // O(n log n) versi optimal untuk interview
    static int lisOptimal(int[] nums) {
        List<Integer> tails = new ArrayList<>();

        for (int num : nums) {
            int lo = 0, hi = tails.size();
            // Binary search posisi yang tepat
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (tails.get(mid) < num) lo = mid + 1;
                else hi = mid;
            }
            if (lo == tails.size()) tails.add(num);
            else tails.set(lo, num);
        }
        return tails.size();
    }

    public static void main(String[] args) {
        int[] nums = {10, 9, 2, 5, 3, 7, 101, 18};
        System.out.println(lisSimple(nums));  // 4 → [2,3,7,101]
        System.out.println(lisOptimal(nums)); // 4
    }
}

