public class StringDP {

    // LeetCode 72 - Edit Distance (Insert/Delete/Replace)
    static int editDistance(String a, String b) {
        int m = a.length(), n = b.length();
        int[][] dp = new int[m + 1][n + 1];

        // Base case
        for (int i = 0; i <= m; i++) dp[i][0] = i;
        for (int j = 0; j <= n; j++) dp[0][j] = j;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (a.charAt(i-1) == b.charAt(j-1)) {
                    dp[i][j] = dp[i-1][j-1]; // tidak perlu edit
                } else {
                    dp[i][j] = 1 + Math.min(dp[i-1][j-1],  // replace
                                   Math.min(dp[i-1][j],     // delete
                                            dp[i][j-1]));   // insert
                }
            }
        }
        return dp[m][n];
    }

    // LeetCode 5 - Longest Palindromic Substring
    static String longestPalindrome(String s) {
        int n = s.length(), start = 0, maxLen = 1;
        boolean[][] dp = new boolean[n][n];

        // Semua karakter tunggal adalah palindrom
        for (int i = 0; i < n; i++) dp[i][i] = true;

        // Cek panjang 2
        for (int i = 0; i < n - 1; i++) {
            if (s.charAt(i) == s.charAt(i + 1)) {
                dp[i][i + 1] = true;
                start = i;
                maxLen = 2;
            }
        }

        // Cek panjang 3+
        for (int len = 3; len <= n; len++) {
            for (int i = 0; i <= n - len; i++) {
                int j = i + len - 1;
                if (s.charAt(i) == s.charAt(j) && dp[i+1][j-1]) {
                    dp[i][j] = true;
                    if (len > maxLen) { start = i; maxLen = len; }
                }
            }
        }
        return s.substring(start, start + maxLen);
    }

    public static void main(String[] args) {
        System.out.println(editDistance("horse", "ros"));   // 3
        System.out.println(longestPalindrome("babad"));     // "bab"
    }
}

public void rotate(int[] nums, int k) {
   if(k > nums.length)
      k=k%nums.length;

   int[] result = new int[nums.length];

   for(int i=0; i < k; i++){
      result[i] = nums[nums.length-k+i];
   }

   int j=0;
   for(int i=k; i<nums.length; i++){
      result[i] = nums[j];
      j++;
   }

   System.arraycopy( result, 0, nums, 0, nums.length );
}

public static void rotate(int[] arr, int order) {
  if (arr == null || order < 0) {
     throw new IllegalArgumentException("Illegal argument!");
  }

  for (int i = 0; i < order; i++) {
    for (int j = arr.length - 1; j > 0; j--) {
       int temp = arr[j];
       arr[j] = arr[j - 1];
       arr[j - 1] = temp;
    }
  }
}

