public int findKthLargest(int[] nums, int k) {
  if (k < 1 || nums == null) {
    return 0;
  }

  return getKth(nums.length - k +1, nums, 0, nums.length - 1);
}

public int getKth(int k, int[] nums, int start, int end) {

  int pivot = nums[end];

  int left = start;
  int right = end;

  while (true) {

    while (nums[left] < pivot && left < right) {
       left++;
    }
    while (nums[right] >= pivot && right > left) {
       right--;
    }

    if (left == right) {
       break;
    }

    swap(nums, left, right);
  }

  swap(nums, left, end);

  if (k == left + 1) {
    return pivot;
  } else if (k < left + 1) {
    return getKth(k, nums, start, left - 1);
  } else {
    return getKth(k, nums, left + 1, end);
  }
}

public void swap(int[] nums, int n1, int n2) {
  int tmp = nums[n1];
  nums[n1] = nums[n2];
  nums[n2] = tmp;
}

public int findKthLargest(int[] nums, int k) {
   PriorityQueue<Integer> q = new PriorityQueue<Integer>(k);
   for(int i: nums){
      q.offer(i);

      if(q.size()>k){
         q.poll();
      }
   }

   return q.peek();
}

public boolean isMatch(String s, String p) {
  int i = 0;
  int j = 0;
  int starIndex = -1;
  int iIndex = -1;

  while (i < s.length()) {
    if (j < p.length() && (p.charAt(j) == ’?’ || p.charAt(j) == s.charAt(i)))
        {
       ++i;
       ++j;
    } else if (j < p.length() && p.charAt(j) == ’*’) {
       starIndex = j;
       iIndex = i;
       j++;
    } else if (starIndex != -1) {
       j = starIndex + 1;
       i = iIndex+1;
       iIndex++;
    } else {
       return false;
    }
  }

  while (j < p.length() && p.charAt(j) == ’*’) {
    ++j;
  }

  return j == p.length();
}

public class Solution {
   public boolean isMatch(String s, String p) {

      if(p.length() == 0)
         return s.length() == 0;

      //p’s length 1 is special case
      if(p.length() == 1 || p.charAt(1) != ’*’){
         if(s.length() < 1 || (p.charAt(0) != ’.’ && s.charAt(0) !=
             p.charAt(0)))
            return false;
         return isMatch(s.substring(1), p.substring(1));

      }else{
         int len = s.length();

         int i = -1;
         while(i<len && (i < 0 || p.charAt(0) == ’.’ || p.charAt(0) ==
             s.charAt(i))){
            if(isMatch(s.substring(i+1), p.substring(2)))
               return true;
            i++;
         }
         return false;
      }
   }
}

public boolean isMatch(String s, String p) {
  // base case
  if (p.length() == 0) {
    return s.length() == 0;
  }

  // special case
  if (p.length() == 1) {

    // if the length of s is 0, return false
    if (s.length() < 1) {
       return false;
    }

    //if the first does not match, return false
    else if ((p.charAt(0) != s.charAt(0)) && (p.charAt(0) != ’.’)) {
       return false;
    }

    // otherwise, compare the rest of the string of s and p.
    else {
       return isMatch(s.substring(1), p.substring(1));
    }
  }

  // case 1: when the second char of p is not ’*’
  if (p.charAt(1) != ’*’) {
    if (s.length() < 1) {
       return false;
    }
    if ((p.charAt(0) != s.charAt(0)) && (p.charAt(0) != ’.’)) {
       return false;
    } else {
       return isMatch(s.substring(1), p.substring(1));
    }
  }

  // case 2: when the second char of p is ’*’, complex case.
  else {
    //case 2.1: a char & ’*’ can stand for 0 element
    if (isMatch(s, p.substring(2))) {
       return true;
    }

    //case 2.2: a char & ’*’ can stand for 1 or more preceding element,
    //so try every sub string
    int i = 0;
    while (i<s.length() && (s.charAt(i)==p.charAt(0) || p.charAt(0)==’.’)){
       if (isMatch(s.substring(i + 1), p.substring(2))) {
         return true;
       }
       i++;
    }
    return false;
  }
}

class Interval {
  int start;
  int end;

  Interval() {
    start = 0;
    end = 0;
  }

  Interval(int s, int e) {
    start = s;
    end = e;
  }
}

public class Solution {
  public ArrayList<Interval> merge(ArrayList<Interval> intervals) {

    if (intervals == null || intervals.size() <= 1)
       return intervals;

    // sort intervals by using self-defined Comparator
    Collections.sort(intervals, new IntervalComparator());

    ArrayList<Interval> result = new ArrayList<Interval>();

    Interval prev = intervals.get(0);
    for (int i = 1; i < intervals.size(); i++) {
       Interval curr = intervals.get(i);

       if (prev.end >= curr.start) {
         // merged case
         Interval merged = new Interval(prev.start, Math.max(prev.end,
             curr.end));
         prev = merged;
       } else {
         result.add(prev);
         prev = curr;
       }
    }

    result.add(prev);

    return result;
  }
}

class IntervalComparator implements Comparator<Interval> {
  public int compare(Interval i1, Interval i2) {
    return i1.start - i2.start;
  }
}

/**
 * Definition for an interval.
 * public class Interval {
 *   int start;
 *   int end;
 *   Interval() { start = 0; end = 0; }
 *   Interval(int s, int e) { start = s; end = e; }
 * }
 */
public class Solution {
   public ArrayList<Interval> insert(ArrayList<Interval> intervals, Interval
       newInterval) {

      ArrayList<Interval> result = new ArrayList<Interval>();

      for(Interval interval: intervals){
         if(interval.end < newInterval.start){
            result.add(interval);
         }else if(interval.start > newInterval.end){
            result.add(newInterval);
            newInterval = interval;
         }else if(interval.end >= newInterval.start || interval.start <=
             newInterval.end){
            newInterval = new Interval(Math.min(interval.start,
                newInterval.start), Math.max(newInterval.end, interval.end));
         }
      }

      result.add(newInterval);

      return result;
   }
}

public static int[] twoSum(int[] numbers, int target) {
  int[] ret = new int[2];
  for (int i = 0; i < numbers.length; i++) {
    for (int j = i + 1; j < numbers.length; j++) {
       if (numbers[i] + numbers[j] == target) {
         ret[0] = i + 1;
         ret[1] = j + 1;
       }
    }
  }
  return ret;
}

public class Solution {
   public int[] twoSum(int[] numbers, int target) {
  HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();
  int[] result = new int[2];
  for (int i = 0; i < numbers.length; i++) {
    if (map.containsKey(numbers[i])) {
       int index = map.get(numbers[i]);
       result[0] = index+1 ;
       result[1] = i+1;
       break;
    } else {
       map.put(target - numbers[i], i);
    }
  }

  return result;
   }
}

public int[] twoSum(int[] numbers, int target) {
  if (numbers == null || numbers.length == 0)
    return null;

  int i = 0;
  int j = numbers.length - 1;

  while (i < j) {
    int x = numbers[i] + numbers[j];
    if (x < target) {
       ++i;
    } else if (x > target) {
       j--;
    } else {
       return new int[] { i + 1, j + 1 };
    }
  }

  return null;
}

