  for (int i = 0; i < arr.length; i++) {
    if (!map.containsKey(arr[i])) {
       map.put(arr[i], i);
    } else {
       pre = Math.max(pre, map.size());
       i = map.get(arr[i]);
       map.clear();
    }
  }

