public int[] searchRange(int[] nums, int target) {
   if(nums == null || nums.length == 0){
      return null;
   }

   int[] arr= new int[2];
   arr[0]=-1;
   arr[1]=-1;

   binarySearch(nums, 0, nums.length-1, target, arr);

   return arr;
}

public void binarySearch(int[] nums, int left, int right, int target, int[]
    arr){
   if(right<left)
      return;

   if(nums[left]==nums[right] && nums[left]==target){
      arr[0]=left;
      arr[1]=right;
      return;
   }

   int mid = left+(right-left)/2;
   if(nums[mid]<target){
      binarySearch(nums, mid+1, right, target, arr);
   }else if(nums[mid]>target){
      binarySearch(nums, left, mid-1, target, arr);
   }else{
      arr[0]=mid;
      arr[1]=mid;

      //handle duplicates - left
      int t1 = mid;
      while(t1 >left && nums[t1]==nums[t1-1]){
         t1--;
         arr[0]=t1;
      }

      //handle duplicates - right
      int t2 = mid;
      while(t2 < right&& nums[t2]==nums[t2+1]){
         t2++;
         arr[1]=t2;
      }
      return;
   }
}

public int calculate(String s) {
  // delte white spaces
  s = s.replaceAll(" ", "");

  Stack<String> stack = new Stack<String>();
  char[] arr = s.toCharArray();

  StringBuilder sb = new StringBuilder();
  for (int i = 0; i < arr.length; i++) {
    if (arr[i] == ’ ’)
       continue;

    if (arr[i] >= ’0’ && arr[i] <= ’9’) {
       sb.append(arr[i]);

       if (i == arr.length - 1) {
         stack.push(sb.toString());
       }
    } else {
       if (sb.length() > 0) {
         stack.push(sb.toString());
         sb = new StringBuilder();
       }

       if (arr[i] != ’)’) {
         stack.push(new String(new char[] { arr[i] }));
       } else {
         // when meet ’)’, pop and calculate
         ArrayList<String> t = new ArrayList<String>();
         while (!stack.isEmpty()) {
           String top = stack.pop();
           if (top.equals("(")) {
             break;
           } else {
             t.add(0, top);
           }
         }

         int temp = 0;
         if (t.size() == 1) {
           temp = Integer.valueOf(t.get(0));
         } else {
           for (int j = t.size() - 1; j > 0; j = j - 2) {
             if (t.get(j - 1).equals("-")) {
                temp += 0 - Integer.valueOf(t.get(j));
             } else {
                temp += Integer.valueOf(t.get(j));
             }
           }
           temp += Integer.valueOf(t.get(0));
         }
         stack.push(String.valueOf(temp));
       }
    }
  }

  ArrayList<String> t = new ArrayList<String>();
  while (!stack.isEmpty()) {
    String elem = stack.pop();
    t.add(0, elem);
  }

  int temp = 0;
  for (int i = t.size() - 1; i > 0; i = i - 2) {
    if (t.get(i - 1).equals("-")) {
       temp += 0 - Integer.valueOf(t.get(i));
    } else {
       temp += Integer.valueOf(t.get(i));
    }
  }
  temp += Integer.valueOf(t.get(0));

  return temp;
}

public List<List<String>> groupAnagrams(String[] strs) {
   List<List<String>> result = new ArrayList<List<String>>();

   HashMap<String, ArrayList<String>> map = new HashMap<String,
       ArrayList<String>>();
   for(String str: strs){
      char[] arr = str.toCharArray();
      Arrays.sort(arr);
      String ns = new String(arr);

      if(map.containsKey(ns)){
         map.get(ns).add(str);
      }else{
         ArrayList<String> al = new ArrayList<String>();
         al.add(str);
         map.put(ns, al);
      }
   }

   for(Map.Entry<String, ArrayList<String>> entry: map.entrySet()){
      Collections.sort(entry.getValue());
   }

   result.addAll(map.values());

   return result;
}

public String shortestPalindrome(String s) {
  if (s == null || s.length() <= 1)
    return s;

  String result = null;

  int len = s.length();
  int mid = len / 2;

  for (int i = mid; i >= 1; i--) {
    if (s.charAt(i) == s.charAt(i - 1)) {
       if ((result = scanFromCenter(s, i - 1, i)) != null)
         return result;
    } else {
       if ((result = scanFromCenter(s, i - 1, i - 1)) != null)
         return result;
    }
  }

  return result;
}

private String scanFromCenter(String s, int l, int r) {
  int i = 1;
  //scan from center to both sides
  for (; l - i >= 0; i++) {
    if (s.charAt(l - i) != s.charAt(r + i))
       break;
  }

  //if not end at the beginning of s, return null
  if (l - i >= 0)
    return null;

  StringBuilder sb = new StringBuilder(s.substring(r + i));
  sb.reverse();

  return sb.append(s).toString();
}

public int computeArea(int A, int B, int C, int D, int E, int F, int G, int
    H) {
   if(C<E||G<A )
      return (G-E)*(H-F) + (C-A)*(D-B);

   if(D<F || H<B)
      return (G-E)*(H-F) + (C-A)*(D-B);

   int right = Math.min(C,G);
   int left = Math.max(A,E);
   int top = Math.min(H,D);
   int bottom = Math.max(F,B);

   return (G-E)*(H-F) + (C-A)*(D-B) - (right-left)*(top-bottom);
}

public List<String> summaryRanges(int[] nums) {
   List<String> result = new ArrayList<String>();

   if(nums == null || nums.length==0)
      return result;

   if(nums.length==1){
      result.add(nums[0]+"");
   }

   int pre = nums[0]; // previous element
   int first = pre; // first element of each range

   for(int i=1; i<nums.length; i++){
         if(nums[i]==pre+1){
            if(i==nums.length-1){
               result.add(first+"->"+nums[i]);
            }
         }else{
            if(first == pre){
               result.add(first+"");
            }else{
               result.add(first + "->"+pre);
            }

            if(i==nums.length-1){
               result.add(nums[i]+"");
            }

            first = nums[i];
         }
         pre = nums[i];
   }

   return result;
}

public boolean increasingTriplet(int[] nums) {
  int x = Integer.MAX_VALUE;
  int y = Integer.MAX_VALUE;

  for (int i = 0; i < nums.length; i++) {
    int z = nums[i];

    if (x >= z) {
       x = z;// update x to be a smaller value
    } else if (y >= z) {
       y = z; // update y to be a smaller value
    } else {
       return true;
    }
  }

  return false;
}

public static boolean isReachable(ArrayList<Integer> list, int target) {
  if (list == null || list.size() == 0)
    return false;

  int i = 0;
  int j = list.size() - 1;

  ArrayList<Integer> results = getResults(list, i, j, target);

  for (int num : results) {
    if (num == target) {
       return true;
    }
  }

  return false;
}

public static ArrayList<Integer> getResults(ArrayList<Integer> list,
    int left, int right, int target) {
  ArrayList<Integer> result = new ArrayList<Integer>();

  if (left > right) {
    return result;
  } else if (left == right) {
    result.add(list.get(left));
    return result;
  }

  for (int i = left; i < right; i++) {

    ArrayList<Integer> result1 = getResults(list, left, i, target);
    ArrayList<Integer> result2 = getResults(list, i + 1, right, target);

    for (int x : result1) {
       for (int y : result2) {
         result.add(x + y);
         result.add(x - y);
         result.add(x * y);
         if (y != 0)
           result.add(x / y);
       }
    }
  }

  return result;
}

public String reverseVowels(String s) {
   ArrayList<Character> vowList = new ArrayList<Character>();
   vowList.add(’a’);
   vowList.add(’e’);
   vowList.add(’i’);
   vowList.add(’o’);
   vowList.add(’u’);
   vowList.add(’A’);
   vowList.add(’E’);
   vowList.add(’I’);
   vowList.add(’O’);
   vowList.add(’U’);

   char[] arr = s.toCharArray();

   int i=0;
   int j=s.length()-1;

   while(i<j){
      if(!vowList.contains(arr[i])){
         i++;
         continue;
      }

      if(!vowList.contains(arr[j])){
         j--;
         continue;
      }

      char t = arr[i];
      arr[i]=arr[j];
      arr[j]=t;

      i++;
      j--;
   }

   return new String(arr);
}

public List<String> generatePossibleNextMoves(String s) {
   List<String> result = new ArrayList<String>();

   if(s==null)
      return result;

   char[] arr = s.toCharArray();
   for(int i=0; i<arr.length-1; i++){
      if(arr[i]==arr[i+1] && arr[i]==’+’){
         arr[i]=’-’;
         arr[i+1]=’-’;
         result.add(new String(arr));
         arr[i]=’+’;
         arr[i+1]=’+’;
      }
   }

   return result;
}

public boolean canWin(String s) {
   if(s==null||s.length()==0){
      return false;
   }

  return canWinHelper(s.toCharArray());
}

public boolean canWinHelper(char[] arr){
   for(int i=0; i<arr.length-1;i++){
      if(arr[i]==’+’&&arr[i+1]==’+’){
         arr[i]=’-’;
         arr[i+1]=’-’;

         boolean win = canWinHelper(arr);

         arr[i]=’+’;
         arr[i+1]=’+’;

         //if there is a flip which makes the other player lose, the first
             play wins
         if(!win){
            return true;
         }
      }
   }

   return false;
}

public void moveZeroes(int[] nums) {
   int m=-1;

   for(int i=0; i<nums.length; i++){
      if(nums[i]==0){
         if(m==-1 || nums[m]!=0){
            m=i;
         }
      }else{
         if(m!=-1){
            int temp = nums[i];
            nums[i]=nums[m];
            nums[m]=temp;
            m++;
         }
      }
   }
}

public boolean isAnagram(String s, String t) {
   if(s.length()!=t.length())
      return false;

   int[] arr = new int[26];
   for(int i=0; i<s.length(); i++){
      char c1 = s.charAt(i);
      arr[c1-’a’]++;
   }

   for(int i=0; i<s.length(); i++){
      char c2 = t.charAt(i);
      if(arr[c2-’a’] == 0){
         return false;
      }else{
         arr[c2-’a’]--;
      }
   }

   for(int i=0; i<26; i++){
      if(arr[i]%2==1){
         return false;
      }
   }

   return true;
}

public boolean isAnagram(String s, String t) {
   if(s.length()!=t.length())
      return false;

   HashMap<Character, Integer> map = new HashMap<Character, Integer>();

   for(int i=0; i<s.length(); i++){
      char c1 = s.charAt(i);
      if(map.containsKey(c1)){
         map.put(c1, map.get(c1)+1);
      }else{
         map.put(c1,1);
      }
   }

   for(int i=0; i<s.length(); i++){
      char c2 = t.charAt(i);
      if(map.containsKey(c2)){
         if(map.get(c2)==1){
            map.remove(c2);
         }else{
            map.put(c2, map.get(c2)-1);
         }
      }else{
         return false;
      }
   }

   if(map.size()>0)
      return false;

   return true;
}

public List<List<String>> groupStrings(String[] strings) {
   List<List<String>> result = new ArrayList<List<String>>();
   HashMap<String, ArrayList<String>> map
               = new HashMap<String, ArrayList<String>>();

   for(String s: strings){
      char[] arr = s.toCharArray();
      if(arr.length>0){
         int diff = arr[0]-’a’;
         for(int i=0; i<arr.length; i++){
            if(arr[i]-diff<’a’){
              arr[i] = (char) (arr[i]-diff+26);
            }else{
              arr[i] = (char) (arr[i]-diff);
            }

         }
      }

      String ns = new String(arr);
      if(map.containsKey(ns)){
         map.get(ns).add(s);
      }else{
         ArrayList<String> al = new ArrayList<String>();
         al.add(s);
         map.put(ns, al);
      }
   }

   for(Map.Entry<String, ArrayList<String>> entry: map.entrySet()){
      Collections.sort(entry.getValue());
   }

   result.addAll(map.values());

   return result;
}

public class Solution {
   public List<Integer> topKFrequent(int[] nums, int k) {
      List<Integer> result = new ArrayList<Integer>();

      HashMap<Integer, Integer> counter = new HashMap<Integer, Integer>();

      for(int i: nums){
         if(counter.containsKey(i)){
            counter.put(i, counter.get(i)+1);
         }else{
            counter.put(i, 1);
         }
      }

      TreeMap<Integer, Integer> sortedMap = new TreeMap<Integer, Integer>(new
          ValueComparator(counter));
      sortedMap.putAll(counter);

      int i=0;
      for(Map.Entry<Integer, Integer> entry: sortedMap.entrySet()){
         result.add(entry.getKey());
         i++;
         if(i==k)
            break;
      }

      return result;
   }
}

class ValueComparator implements Comparator<Integer>{
   HashMap<Integer, Integer> map = new HashMap<Integer, Integer>();

   public ValueComparator(HashMap<Integer, Integer> m){
      map.putAll(m);
   }
   public int compare(Integer i1, Integer i2){
      int diff = map.get(i2)-map.get(i1);

      if(diff==0){
         return 1;
      }else{
         return diff;
      }
   }
}

public class Solution {
   public int findPeakElement(int[] num) {
      int max = num[0];
      int index = 0;
      for(int i=1; i<=num.length-2; i++){
         int prev = num[i-1];
         int curr = num[i];
         int next = num[i+1];

         if(curr > prev && curr > next && curr > max){
            index = i;
            max = curr;
         }
      }

      if(num[num.length-1] > max){
         return num.length-1;
      }

      return index;
   }
}

public boolean wordPattern(String pattern, String str) {
   String[] arr = str.split(" ");

   if(pattern.length()!=arr.length)
      return false;

   HashMap<Character, String> map = new HashMap<Character, String>();

   for(int i=0; i<arr.length; i++){
      char c = pattern.charAt(i);
      String s = arr[i];

      if(map.containsKey(c)){
         if(!map.get(c).equals(s))
            return false;

      }else{
         if(map.containsValue(s))
            return false;

         map.put(c, s);
      }
   }

   return true;
}

public class Solution {
   public void setZeroes(int[][] matrix) {
      boolean firstRowZero = false;
      boolean firstColumnZero = false;

      //set first row and column zero or not
      for(int i=0; i<matrix.length; i++){
         if(matrix[i][0] == 0){
            firstColumnZero = true;
            break;
         }
      }

      for(int i=0; i<matrix[0].length; i++){
         if(matrix[0][i] == 0){
            firstRowZero = true;
            break;
         }
      }
      //mark zeros on first row and column
      for(int i=1; i<matrix.length; i++){
         for(int j=1; j<matrix[0].length; j++){
            if(matrix[i][j] == 0){
              matrix[i][0] = 0;
              matrix[0][j] = 0;
            }
         }
      }

      //use mark to set elements
      for(int i=1; i<matrix.length; i++){
         for(int j=1; j<matrix[0].length; j++){
            if(matrix[i][0] == 0 || matrix[0][j] == 0){
              matrix[i][j] = 0;
            }
         }
      }

      //set first column and row
      if(firstColumnZero){
         for(int i=0; i<matrix.length; i++)
            matrix[i][0] = 0;
      }

      if(firstRowZero){
         for(int i=0; i<matrix[0].length; i++)
            matrix[0][i] = 0;
      }

   }
}

public class Solution {
   public ArrayList<Integer> spiralOrder(int[][] matrix) {
      ArrayList<Integer> result = new ArrayList<Integer>();

      if(matrix == null || matrix.length == 0) return result;

      int m = matrix.length;
      int n = matrix[0].length;

      int x=0;
      int y=0;

      while(m>0 && n>0){

         //if one row/column left, no circle can be formed
         if(m==1){
            for(int i=0; i<n; i++){
               result.add(matrix[x][y++]);
            }
            break;
         }else if(n==1){
            for(int i=0; i<m; i++){
               result.add(matrix[x++][y]);
            }
            break;
         }

         //below, process a circle

         //top - move right
         for(int i=0;i<n-1;i++){
            result.add(matrix[x][y++]);
         }

         //right - move down
         for(int i=0;i<m-1;i++){
            result.add(matrix[x++][y]);
         }

         //bottom - move left
         for(int i=0;i<n-1;i++){
            result.add(matrix[x][y--]);
         }

         //left - move up
         for(int i=0;i<m-1;i++){
            result.add(matrix[x--][y]);
         }

         x++;
         y++;
         m=m-2;
         n=n-2;
      }

      return result;
   }
}

public class Solution {
   public ArrayList<Integer> spiralOrder(int[][] matrix) {
      if(matrix==null || matrix.length==0)
         return new ArrayList<Integer>();

      return spiralOrder(matrix,0,0,matrix.length,matrix[0].length);
   }
   public ArrayList<Integer> spiralOrder(int [][] matrix, int x, int y, int
       m, int n){
      ArrayList<Integer> result = new ArrayList<Integer>();

      if(m<=0||n<=0)
         return result;

      //only one element left
      if(m==1&&n==1) {
         result.add(matrix[x][y]);
         return result;
      }

      //top - move right
      for(int i=0;i<n-1;i++){
         result.add(matrix[x][y++]);
      }

      //right - move down
      for(int i=0;i<m-1;i++){
         result.add(matrix[x++][y]);
      }

      //bottom - move left
      if(m>1){
         for(int i=0;i<n-1;i++){
            result.add(matrix[x][y--]);
         }
      }

      //left - move up
      if(n>1){
         for(int i=0;i<m-1;i++){
            result.add(matrix[x--][y]);
         }
      }

      if(m==1||n==1)
         result.addAll(spiralOrder(matrix, x, y, 1, 1));
      else
         result.addAll(spiralOrder(matrix, x+1, y+1, m-2, n-2));

      return result;
   }
}

public int[][] generateMatrix(int n) {
   int total = n*n;
   int[][] result= new int[n][n];

   int x=0;
   int y=0;
   int step = 0;

   for(int i=0;i<total;){
      while(y+step<n){
         i++;
         result[x][y]=i;
         y++;

      }
      y--;
      x++;

      while(x+step<n){
         i++;
         result[x][y]=i;
         x++;
      }
      x--;
      y--;

      while(y>=0+step){
         i++;
         result[x][y]=i;
         y--;
      }
      y++;
      x--;
      step++;

      while(x>=0+step){
         i++;
         result[x][y]=i;
         x--;
      }
      x++;
      y++;
   }

   return result;
}

public class Solution {
   public boolean searchMatrix(int[][] matrix, int target) {
      if(matrix==null || matrix.length==0 || matrix[0].length==0)
         return false;

      int m = matrix.length;
      int n = matrix[0].length;

      int start = 0;
      int end = m*n-1;

      while(start<=end){
         int mid=(start+end)/2;
         int midX=mid/n;
         int midY=mid%n;

         if(matrix[midX][midY]==target)
            return true;
         if(matrix[midX][midY]<target){
            start=mid+1;
         }else{
            end=mid-1;
         }
      }

      return false;
   }
}

public boolean searchMatrix(int[][] matrix, int target) {
   int i1=0;
   int i2=matrix.length-1;
   int j1=0;
   int j2=matrix[0].length-1;

   return helper(matrix, i1, i2, j1, j2, target);
}

public boolean helper(int[][] matrix, int i1, int i2, int j1, int j2, int
    target){

   if(i1>i2||j1>j2)
      return false;

   for(int j=j1;j<=j2;j++){
      if(target < matrix[i1][j]){
         return helper(matrix, i1, i2, j1, j-1, target);
      }else if(target == matrix[i1][j]){
         return true;
      }
   }

   for(int i=i1;i<=i2;i++){
      if(target < matrix[i][j1]){
         return helper(matrix, i1, i-1, j1, j2, target);
      }else if(target == matrix[i][j1]){
         return true;
      }
   }

   for(int j=j1;j<=j2;j++){
      if(target > matrix[i2][j]){
         return helper(matrix, i1, i2, j+1, j2, target);
      }else if(target == matrix[i2][j]){
         return true;
      }
   }

   for(int i=i1;i<=i2;i++){
      if(target > matrix[i][j2]){
         return helper(matrix, i1, i+1, j1, j2, target);
      }else if(target == matrix[i][j2]){
         return true;
      }
   }

   return false;
}

public boolean searchMatrix(int[][] matrix, int target) {
   int m=matrix.length-1;
   int n=matrix[0].length-1;

   int i=m;
   int j=0;

   while(i>=0 && j<=n){
      if(target < matrix[i][j]){
         i--;
      }else if(target > matrix[i][j]){
         j++;
      }else{
         return true;
      }
   }

   return false;
}

public class Solution {
   public void rotate(int[][] matrix) {
      if(matrix == null || matrix.length==0)
         return ;

      int m = matrix.length;

      int[][] result = new int[m][m];

      for(int i=0; i<m; i++){
         for(int j=0; j<m; j++){
            result[j][m-1-i] = matrix[i][j];
         }
      }

      matrix = result;
   }
}

public class Solution {
   public void rotate(int[][] matrix) {
      if(matrix == null || matrix.length==0)
         return ;

      int m = matrix.length;
      int[][] result = new int[m][m];

      for(int i=0; i<m; i++){
         for(int j=0; j<m; j++){
            result[j][m-1-i] = matrix[i][j];
         }
      }

     for(int i=0; i<m; i++){
         for(int j=0; j<m; j++){
            matrix[i][j] = result[i][j];
         }
      }
   }
}

public void rotate(int[][] matrix) {
  int n = matrix.length;
  for (int i = 0; i < n / 2; i++) {
    for (int j = 0; j < Math.ceil(((double) n) / 2.); j++) {
       int temp = matrix[i][j];
       matrix[i][j] = matrix[n-1-j][i];
       matrix[n-1-j][i] = matrix[n-1-i][n-1-j];
       matrix[n-1-i][n-1-j] = matrix[j][n-1-i];
       matrix[j][n-1-i] = temp;
    }
  }
}

public boolean isValidSudoku(char[][] board) {
  if (board == null || board.length != 9 || board[0].length != 9)
    return false;
  // check each column
  for (int i = 0; i < 9; i++) {
    boolean[] m = new boolean[9];
    for (int j = 0; j < 9; j++) {
       if (board[i][j] != ’.’) {
         if (m[(int) (board[i][j] - ’1’)]) {
           return false;
         }
         m[(int) (board[i][j] - ’1’)] = true;
       }
    }
  }

  //check each row
  for (int j = 0; j < 9; j++) {
    boolean[] m = new boolean[9];
    for (int i = 0; i < 9; i++) {
       if (board[i][j] != ’.’) {
         if (m[(int) (board[i][j] - ’1’)]) {
           return false;
         }
         m[(int) (board[i][j] - ’1’)] = true;
       }
    }
  }

  //check each 3*3 matrix
  for (int block = 0; block < 9; block++) {
    boolean[] m = new boolean[9];
    for (int i = block / 3 * 3; i < block / 3 * 3 + 3; i++) {
       for (int j = block % 3 * 3; j < block % 3 * 3 + 3; j++) {
         if (board[i][j] != ’.’) {
           if (m[(int) (board[i][j] - ’1’)]) {
             return false;
           }
           m[(int) (board[i][j] - ’1’)] = true;
         }
       }
    }
  }

  return true;
}

public int minPathSum(int[][] grid) {
   return dfs(0,0,grid);
}

public int dfs(int i, int j, int[][] grid){
   if(i==grid.length-1 && j==grid[0].length-1){
      return grid[i][j];
   }

   if(i<grid.length-1 && j<grid[0].length-1){
      int r1 = grid[i][j] + dfs(i+1, j, grid);
      int r2 = grid[i][j] + dfs(i, j+1, grid);
      return Math.min(r1,r2);
   }

   if(i<grid.length-1){
      return grid[i][j] + dfs(i+1, j, grid);
   }

   if(j<grid[0].length-1){
      return grid[i][j] + dfs(i, j+1, grid);
   }

   return 0;
}

public int minPathSum(int[][] grid) {
   if(grid == null || grid.length==0)
      return 0;
   int m = grid.length;
   int n = grid[0].length;

   int[][] dp = new int[m][n];
   dp[0][0] = grid[0][0];

   // initialize top row
   for(int i=1; i<n; i++){
      dp[0][i] = dp[0][i-1] + grid[0][i];
   }

   // initialize left column
   for(int j=1; j<m; j++){
      dp[j][0] = dp[j-1][0] + grid[j][0];
   }

   // fill up the dp table
   for(int i=1; i<m; i++){
      for(int j=1; j<n; j++){
         if(dp[i-1][j] > dp[i][j-1]){
            dp[i][j] = dp[i][j-1] + grid[i][j];
         }else{
            dp[i][j] = dp[i-1][j] + grid[i][j];
         }
      }
   }

   return dp[m-1][n-1];
}

public int uniquePaths(int m, int n) {
   return dfs(0,0,m,n);
}

public int dfs(int i, int j, int m, int n){
   if(i==m-1 && j==n-1){
      return 1;
   }

   if(i<m-1 && j<n-1){
      return dfs(i+1,j,m,n) + dfs(i,j+1,m,n);
   }

   if(i<m-1){
      return dfs(i+1,j,m,n);
   }

   if(j<n-1){
      return dfs(i,j+1,m,n);
   }

   return 0;
}

public int uniquePaths(int m, int n) {
   if(m==0 || n==0) return 0;
   if(m==1 || n==1) return 1;
   int[][] dp = new int[m][n];

   //left column
   for(int i=0; i<m; i++){
      dp[i][0] = 1;
   }

   //top row
   for(int j=0; j<n; j++){
      dp[0][j] = 1;
   }

   //fill up the dp table
   for(int i=1; i<m; i++){
      for(int j=1; j<n; j++){
         dp[i][j] = dp[i-1][j] + dp[i][j-1];
      }
   }

   return dp[m-1][n-1];
}

public int uniquePathsWithObstacles(int[][] obstacleGrid) {
   if(obstacleGrid==null||obstacleGrid.length==0)
      return 0;

   int m = obstacleGrid.length;
   int n = obstacleGrid[0].length;

   if(obstacleGrid[0][0]==1||obstacleGrid[m-1][n-1]==1)
      return 0;

   int[][] dp = new int[m][n];
   dp[0][0]=1;

   //left column
   for(int i=1; i<m; i++){
      if(obstacleGrid[i][0]==1){
         dp[i][0] = 0;
      }else{
         dp[i][0] = dp[i-1][0];
      }
   }

   //top row
   for(int i=1; i<n; i++){
      if(obstacleGrid[0][i]==1){
         dp[0][i] = 0;
      }else{
         dp[0][i] = dp[0][i-1];
      }
   }

   //fill up cells inside
   for(int i=1; i<m; i++){
      for(int j=1; j<n; j++){
         if(obstacleGrid[i][j]==1){
            dp[i][j]=0;
         }else{
            dp[i][j]=dp[i-1][j]+dp[i][j-1];
         }

      }
   }

   return dp[m-1][n-1];
}

public int numIslands(char[][] grid) {
   if(grid==null||grid.length==0||grid[0].length==0)
      return 0;

   int m=grid.length;
   int n=grid[0].length;

   int count=0;
   for(int i=0;i<m; i++){
      for(int j=0;j<n; j++){
         if(grid[i][j]==’1’){
            count++;
            merge(grid, i, j);
         }
      }
   }
   return count;
}

public void merge(char[][] grid, int i, int j){
   if(i<0||j<0||i>=grid.length||j>=grid[0].length)
      return;

   if(grid[i][j]==’1’){
      grid[i][j]=’0’;

      merge(grid, i-1,j);
      merge(grid, i+1,j);
      merge(grid, i,j-1);
      merge(grid, i,j+1);
   }
}

public List<Integer> numIslands2(int m, int n, int[][] positions) {
   int[] rootArray = new int[m*n];
   Arrays.fill(rootArray,-1);

   ArrayList<Integer> result = new ArrayList<Integer>();

   int[][] directions = {{-1,0},{0,1},{1,0},{0,-1}};
   int count=0;

   for(int k=0; k<positions.length; k++){
      count++;

      int[] p = positions[k];
      int index = p[0]*n+p[1];
      rootArray[index]=index;//set root to be itself for each node

      for(int r=0;r<4;r++){
         int i=p[0]+directions[r][0];
         int j=p[1]+directions[r][1];

         if(i>=0&&j>=0&&i<m&&j<n&&rootArray[i*n+j]!=-1){
            //get neighbor’s root
            int thisRoot = getRoot(rootArray, i*n+j);
            if(thisRoot!=index){
               rootArray[thisRoot]=index;//set previous root’s root
               count--;
            }
         }
      }
      result.add(count);
   }

   return result;
}

public int getRoot(int[] arr, int i){
   while(i!=arr[i]){
      i=arr[arr[i]];
   }
   return i;
}

public void solve(char[][] board) {
   if(board == null || board.length==0)
      return;

   int m = board.length;
   int n = board[0].length;

   //merge O’s on left & right boarder
   for(int i=0;i<m;i++){
      if(board[i][0] == ’O’){
         merge(board, i, 0);
      }

      if(board[i][n-1] == ’O’){
         merge(board, i,n-1);
      }
   }

   //merge O’s on top & bottom boarder
   for(int j=0; j<n; j++){
       if(board[0][j] == ’O’){
         merge(board, 0,j);
      }

      if(board[m-1][j] == ’O’){
         merge(board, m-1,j);
      }
   }

   //process the board
   for(int i=0;i<m;i++){
      for(int j=0; j<n; j++){
         if(board[i][j] == ’O’){
            board[i][j] = ’X’;
         }else if(board[i][j] == ’#’){
            board[i][j] = ’O’;
         }
      }
   }
}

public void merge(char[][] board, int i, int j){
   if(i<0 || i>=board.length || j<0 || j>=board[0].length)
      return;

   if(board[i][j] != ’O’)
      return;

   board[i][j] = ’#’;

   merge(board, i-1, j);
   merge(board, i+1, j);
   merge(board, i, j-1);
   merge(board, i, j+1);
}

public class Solution {
  // use a queue to do BFS
  private Queue<Integer> queue = new LinkedList<Integer>();

  public void solve(char[][] board) {
    if (board == null || board.length == 0)
       return;

    int m = board.length;
    int n = board[0].length;

    // merge O’s on left & right boarder
    for (int i = 0; i < m; i++) {
       if (board[i][0] == ’O’) {
         bfs(board, i, 0);
       }

       if (board[i][n - 1] == ’O’) {
         bfs(board, i, n - 1);
       }
    }

    // merge O’s on top & bottom boarder
    for (int j = 0; j < n; j++) {
       if (board[0][j] == ’O’) {
         bfs(board, 0, j);
       }

       if (board[m - 1][j] == ’O’) {
         bfs(board, m - 1, j);
       }
    }

    // process the board
    for (int i = 0; i < m; i++) {
       for (int j = 0; j < n; j++) {
         if (board[i][j] == ’O’) {
           board[i][j] = ’X’;
         } else if (board[i][j] == ’#’) {
           board[i][j] = ’O’;
         }
       }
    }
  }

  private void bfs(char[][] board, int i, int j) {
    int n = board[0].length;

    // fill current first and then its neighbors
    fillCell(board, i, j);
    while (!queue.isEmpty()) {
       int cur = queue.poll();
       int x = cur / n;
       int y = cur % n;

       fillCell(board, x - 1, y);
       fillCell(board, x + 1, y);
       fillCell(board, x, y - 1);
       fillCell(board, x, y + 1);
    }
  }

  private void fillCell(char[][] board, int i, int j) {
    int m = board.length;
    int n = board[0].length;
    if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != ’O’)
       return;

    // add current cell is queue & then process its neighbors in bfs
    queue.offer(i * n + j);
    board[i][j] = ’#’;
  }
}

public int maximalRectangle(char[][] matrix) {
  int m = matrix.length;
  int n = m == 0 ? 0 : matrix[0].length;
  int[][] height = new int[m][n + 1];

  int maxArea = 0;
  for (int i = 0; i < m; i++) {
    for (int j = 0; j < n; j++) {
       if (matrix[i][j] == ’0’) {
         height[i][j] = 0;
       } else {
         height[i][j] = i == 0 ? 1 : height[i - 1][j] + 1;
       }
    }
  }

  for (int i = 0; i < m; i++) {
    int area = maxAreaInHist(height[i]);
    if (area > maxArea) {
       maxArea = area;
    }
  }

  return maxArea;
}

private int maxAreaInHist(int[] height) {
  Stack<Integer> stack = new Stack<Integer>();

  int i = 0;
  int max = 0;
  while (i < height.length) {
    if (stack.isEmpty() || height[stack.peek()] <= height[i]) {
       stack.push(i++);
    } else {
       int t = stack.pop();
       max = Math.max(max, height[t]
           * (stack.isEmpty() ? i : i - stack.peek() - 1));
    }
  }

  return max;
}

public int maximalSquare(char[][] matrix) {
  if (matrix == null || matrix.length == 0 || matrix[0].length == 0)
    return 0;

  int m = matrix.length;
  int n = matrix[0].length;

  int[][] t = new int[m][n];

  //top row
  for (int i = 0; i < m; i++) {
    t[i][0] = Character.getNumericValue(matrix[i][0]);
  }

  //left column
  for (int j = 0; j < n; j++) {
    t[0][j] = Character.getNumericValue(matrix[0][j]);
  }

  //cells inside
  for (int i = 1; i < m; i++) {
    for (int j = 1; j < n; j++) {
       if (matrix[i][j] == ’1’) {
         int min = Math.min(t[i - 1][j], t[i - 1][j - 1]);
         min = Math.min(min,t[i][j - 1]);
         t[i][j] = min + 1;
       } else {
         t[i][j] = 0;
       }
    }
  }

  int max = 0;
  //get maximal length
  for (int i = 0; i < m; i++) {
    for (int j = 0; j < n; j++) {
       if (t[i][j] > max) {
         max = t[i][j];
       }
    }
  }

  return max * max;
}

public boolean exist(char[][] board, String word) {
   int m = board.length;
   int n = board[0].length;

   boolean result = false;
   for(int i=0; i<m; i++){
      for(int j=0; j<n; j++){
        if(dfs(board,word,i,j,0)){
           result = true;
        }
      }
   }

   return result;
}

public boolean dfs(char[][] board, String word, int i, int j, int k){
   int m = board.length;
   int n = board[0].length;

   if(i<0 || j<0 || i>=m || j>=n){
      return false;
   }

   if(board[i][j] == word.charAt(k)){
      char temp = board[i][j];
      board[i][j]=’#’;
      if(k==word.length()-1){
         return true;
      }else if(dfs(board, word, i-1, j, k+1)
      ||dfs(board, word, i+1, j, k+1)
      ||dfs(board, word, i, j-1, k+1)
      ||dfs(board, word, i, j+1, k+1)){
         return true;
      }
      board[i][j]=temp;
   }

   return false;
}

public List<String> findWords(char[][] board, String[] words) {
  ArrayList<String> result = new ArrayList<String>();

  int m = board.length;
  int n = board[0].length;

  for (String word : words) {
    boolean flag = false;
    for (int i = 0; i < m; i++) {
       for (int j = 0; j < n; j++) {
         char[][] newBoard = new char[m][n];
         for (int x = 0; x < m; x++)
           for (int y = 0; y < n; y++)
             newBoard[x][y] = board[x][y];

         if (dfs(newBoard, word, i, j, 0)) {
           flag = true;
         }
       }
    }
    if (flag) {
       result.add(word);
    }
  }

  return result;
}

public boolean dfs(char[][] board, String word, int i, int j, int k) {
  int m = board.length;
  int n = board[0].length;

  if (i < 0 || j < 0 || i >= m || j >= n || k > word.length() - 1) {
    return false;
  }

  if (board[i][j] == word.charAt(k)) {
    char temp = board[i][j];
    board[i][j] = ’#’;

    if (k == word.length() - 1) {
       return true;
    } else if (dfs(board, word, i - 1, j, k + 1)
         || dfs(board, word, i + 1, j, k + 1)
         || dfs(board, word, i, j - 1, k + 1)
         || dfs(board, word, i, j + 1, k + 1)) {
       board[i][j] = temp;
       return true;
    }

  } else {
    return false;
  }

  return false;
}

public class Solution {
   Set<String> result = new HashSet<String>();

   public List<String> findWords(char[][] board, String[] words) {
      //HashSet<String> result = new HashSet<String>();

      Trie trie = new Trie();
      for(String word: words){
         trie.insert(word);
      }

      int m=board.length;
      int n=board[0].length;

      boolean[][] visited = new boolean[m][n];

      for(int i=0; i<m; i++){
         for(int j=0; j<n; j++){
           dfs(board, visited, "", i, j, trie);
         }
      }

      return new ArrayList<String>(result);
   }

   public void dfs(char[][] board, boolean[][] visited, String str, int i,
       int j, Trie trie){
      int m=board.length;
      int n=board[0].length;

      if(i<0 || j<0||i>=m||j>=n){
         return;
      }

      if(visited[i][j])
         return;

      str = str + board[i][j];

      if(!trie.startsWith(str))
         return;

      if(trie.search(str)){
         result.add(str);
      }

      visited[i][j]=true;
      dfs(board, visited, str, i-1, j, trie);
      dfs(board, visited, str, i+1, j, trie);
      dfs(board, visited, str, i, j-1, trie);
      dfs(board, visited, str, i, j+1, trie);
      visited[i][j]=false;
   }
}

//Trie Node
class TrieNode{
   public TrieNode[] children = new TrieNode[26];
   public String item = "";
}

//Trie
class Trie{
   public TrieNode root = new TrieNode();

   public void insert(String word){
      TrieNode node = root;
      for(char c: word.toCharArray()){
         if(node.children[c-’a’]==null){
            node.children[c-’a’]= new TrieNode();
         }
         node = node.children[c-’a’];
      }
      node.item = word;
   }

   public boolean search(String word){
      TrieNode node = root;
      for(char c: word.toCharArray()){
         if(node.children[c-’a’]==null)
            return false;
         node = node.children[c-’a’];
      }
      if(node.item.equals(word)){
         return true;
      }else{
         return false;
      }
   }

   public boolean startsWith(String prefix){
      TrieNode node = root;
      for(char c: prefix.toCharArray()){
         if(node.children[c-’a’]==null)
            return false;
         node = node.children[c-’a’];
      }
      return true;
   }
}

public int integerBreak(int n) {
   int[] dp = new int[n+1];

   for(int i=1; i<n; i++){
      for(int j=1; j<i+1; j++){
         if(i+j<=n){
            dp[i+j]=Math.max(Math.max(dp[i],i)*Math.max(dp[j],j), dp[i+j]);
         }
      }
   }

   return dp[n];
}

public int integerBreak(int n) {

   if(n==2) return 1;
   if(n==3) return 2;
   if(n==4) return 4;

   int result=1;
   if(n%3==0){
      int m = n/3;
      result = (int) Math.pow(3, m);
   }else if(n%3==2){
      int m=n/3;
      result = (int) Math.pow(3, m) * 2;
   }else if(n%3==1){
      int m=(n-4)/3;
      result = (int) Math.pow(3, m) *4;
   }

   return result;
}

public class NumMatrix {
   int [][] sum;

   public NumMatrix(int[][] matrix) {
      if(matrix==null || matrix.length==0||matrix[0].length==0)
         return;

      int m = matrix.length;
      int n = matrix[0].length;
      sum = new int[m][n];

      for(int i=0; i<m; i++){
         int sumRow=0;
         for(int j=0; j<n; j++){
            if(i==0){
               sumRow += matrix[i][j];
               sum[i][j]=sumRow;
            }else{
               sumRow += matrix[i][j];
               sum[i][j]=sumRow+sum[i-1][j];
            }

         }
      }
   }

   public int sumRegion(int row1, int col1, int row2, int col2) {
      if(this.sum==null)
         return 0;

      int topRightX = row1;
      int topRightY = col2;

      int bottomLeftX=row2;
      int bottomLeftY= col1;

      int result=0;

      if(row1==0 && col1==0){
         result = sum[row2][col2];
      }else if(row1==0){
         result = sum[row2][col2]
               -sum[bottomLeftX][bottomLeftY-1];

      }else if(col1==0){
         result = sum[row2][col2]
               -sum[topRightX-1][topRightY];
      }else{
         result = sum[row2][col2]
               -sum[topRightX-1][topRightY]
               -sum[bottomLeftX][bottomLeftY-1]
               +sum[row1-1][col1-1];
      }

      return result;
   }
}

public class Solution {
   int longest=0;

   public int longestIncreasingPath(int[][] matrix) {
      if(matrix==null||matrix.length==0||matrix[0].length==0)
         return 0;

      for(int i=0; i<matrix.length; i++){
         for(int j=0; j<matrix[0].length; j++){
            helper(matrix, i, j, 1);
         }
      }

      return longest;
   }

   public void helper(int[][] matrix, int i, int j, int len){

      if(i-1>=0 && matrix[i-1][j]>matrix[i][j]){
         longest = Math.max(longest, len+1);
         helper(matrix, i-1, j, len+1);
      }

      if(i+1<matrix.length && matrix[i+1][j]>matrix[i][j]){
         longest = Math.max(longest, len+1);
         helper(matrix, i+1, j, len+1);
      }

      if(j-1>=0 && matrix[i][j-1]>matrix[i][j]){
         longest = Math.max(longest, len+1);
         helper(matrix, i, j-1, len+1);
      }
      if(j+1<matrix[0].length && matrix[i][j+1]>matrix[i][j]){
         longest = Math.max(longest, len+1);
         helper(matrix, i, j+1, len+1);
      }

   }
}

public class Solution {
   int[] dx = {-1, 1, 0, 0};
   int[] dy = {0, 0, -1, 1};

   public int longestIncreasingPath(int[][] matrix) {
      if(matrix==null||matrix.length==0||matrix[0].length==0)
         return 0;

      int[][] mem = new int[matrix.length][matrix[0].length];
      int longest=0;

      for(int i=0; i<matrix.length; i++){
         for(int j=0; j<matrix[0].length; j++){
            longest = Math.max(longest, dfs(matrix, i, j, mem));
         }
      }

      return longest;
   }

   public int dfs(int[][] matrix, int i, int j, int[][] mem){
      if(mem[i][j]!=0)
         return mem[i][j];

      for(int m=0; m<4; m++){
         int x = i+dx[m];
         int y = j+dy[m];

         if(x>=0&&y>=0&&x<matrix.length&&y<matrix[0].length&&matrix[x][y]>matrix[i][j]){
            mem[i][j]=Math.max(mem[i][j], dfs(matrix, x, y, mem));
         }
      }

      return ++mem[i][j];
   }
}

public class Stack<E> {
  private E[] arr = null;
  private int CAP;
  private int top = -1;
  private int size = 0;

  @SuppressWarnings("unchecked")
  public Stack(int cap) {
    this.CAP = cap;
    this.arr = (E[]) new Object[cap];
  }

  public E pop() {
    if(this.size == 0){
       return null;
    }

    this.size--;
    E result = this.arr[top];
    this.arr[top] = null;//prevent memory leaking
    this.top--;

    return result;
  }

  public boolean push(E e) {
    if (!isFull())
       return false;
    this.size++;
    this.arr[++top] = e;
    return false;
  }

  public boolean isFull() {
    if (this.size == this.CAP)
       return false;
    return true;
  }

  public String toString() {
    if(this.size==0){
       return null;
    }

    StringBuilder sb = new StringBuilder();
    for(int i=0; i<this.size; i++){
       sb.append(this.arr[i] + ", ");
    }

    sb.setLength(sb.length()-2);
    return sb.toString();
  }

  public static void main(String[] args) {

