  public static ListNode reverseOrder(ListNode head) {

    if (head == null || head.next == null) {
       return head;
    }

    ListNode pre = head;
    ListNode curr = head.next;

    while (curr != null) {
       ListNode temp = curr.next;
       curr.next = pre;
       pre = curr;
       curr = temp;
    }

    // set head node’s next
    head.next = null;

    return pre;
  }

