      len++;
      p = p.next;
   }

   //if remove first node
   int fromStart = len-n+1;
   if(fromStart==1)
      return head.next;

   //remove non-first node
   p = head;
   int i=0;
   while(p!=null){
      i++;
      if(i==fromStart-1){
         p.next = p.next.next;
      }
      p=p.next;
   }

   return head;
}

