public class Queue<E> {

  E[] arr;
  int head = -1;
  int tail = -1;
  int size;

  public Queue(Class<E> c, int size) {
    E[] newInstance = (E[]) Array.newInstance(c, size);
    this.arr = newInstance;
    this.size = 0;
  }

  boolean push(E e) {
    if (size == arr.length)
       return false;

    head = (head + 1) % arr.length;
    arr[head] = e;
    size++;

    if(tail == -1){
       tail = head;
    }
    return true;
  }

  boolean pop() {
    if (size == 0) {
       return false;
    }

    E result = arr[tail];
    arr[tail] = null;
    size--;
    tail = (tail+1)%arr.length;

    if (size == 0) {
       head = -1;
       tail = -1;
    }

    return true;
  }

  E peek(){
    if(size==0)
       return null;

    return arr[tail];
  }

