        return count( S, m - 1, n ) +
            count( S, m, n - S[m - 1] );
    }

    // Driver program
    public static void Main()
    {

        int []arr = {1, 2, 3};
        int m = arr.Length;
        Console.Write( count(arr, m, 4));


    }
}
