  for (int i = n - 2; i >= 0; i--) {

    int max_smaller = INT_MIN;
    for (int j = M - 1; j >= 0; j--) {
      if (a[i][j] < prev &&
          a[i][j] > max_smaller)
        max_smaller = a[i][j];
    }

    // max_smaller equals to INT_MIN means
    // no element is found in a[i] so
    // return 0
    if (max_smaller == INT_MIN)
      return 0;

    prev = max_smaller;
    sum += max_smaller;
  }

  return sum;
}

