        // Semua kerumitan disembunyikan di sini
        if (!inventory.checkStock(productId, qty))
            throw new RuntimeException("Stok tidak cukup");

        inventory.reserveStock(productId, qty);
        double total     = pricing.calculateTotal(productId, qty, coupon);
        String shippingInfo = shipping.calculateShipping(address);
        String orderId   = "ORD-" + System.currentTimeMillis();
        String eta       = shipping.scheduleDelivery(orderId, address);
        notification.sendOrderConfirmation(email, orderId);

        return new OrderSummary(orderId, total, shippingInfo, eta);
    }
}

