// Proxy dengan caching
public class CachingUserRepositoryProxy implements UserRepository {
    private final UserRepository realRepository;
    private final Map<Long, User> cache = new ConcurrentHashMap<>();
    private final long cacheTTL = 5 * 60 * 1000L; // 5 menit
    private final Map<Long, Long> cacheTimestamps = new ConcurrentHashMap<>();

    public CachingUserRepositoryProxy(UserRepository repository) {
        this.realRepository = repository;
    }

    @Override
    public User findById(Long id) {
        Long timestamp = cacheTimestamps.get(id);
        if (timestamp != null &&
            (System.currentTimeMillis() - timestamp) < cacheTTL) {
            System.out.println("Cache HIT untuk user ID: " + id);
            return cache.get(id);
        }
        System.out.println("Cache MISS — mengambil dari database");
        User user = realRepository.findById(id);
        cache.put(id, user);
        cacheTimestamps.put(id, System.currentTimeMillis());
        return user;
    }

    @Override
    public List<User> findAll() {
        return realRepository.findAll();
    }
}

