// Observer interface
public interface OrderObserver {
    void onOrderStatusChanged(Order order, OrderStatus newStatus);
}

// Subject interface
public interface OrderSubject {
    void addObserver(OrderObserver observer);
    void removeObserver(OrderObserver observer);
    void notifyObservers(OrderStatus newStatus);
}

// Concrete Subject
public class Order implements OrderSubject {
    private final String orderId;
    private OrderStatus status;
    private final List<OrderObserver> observers = new ArrayList<>();

    public Order(String orderId) { this.orderId = orderId; }

    @Override public void addObserver(OrderObserver o)    { observers.add(o); }
    @Override public void removeObserver(OrderObserver o) { observers.remove(o); }
    @Override public void notifyObservers(OrderStatus newStatus) {
        observers.forEach(o -> o.onOrderStatusChanged(this, newStatus));
    }

    public void updateStatus(OrderStatus newStatus) {
        this.status = newStatus;
        notifyObservers(newStatus);
    }
    public String getOrderId() { return orderId; }
}

// Concrete Observers
