// Strategy interface
public interface ShippingStrategy {
    double calculateCost(double weightKg, String destination);
    int estimateDeliveryDays(String destination);
    String getCourierName();
}

// Berbagai strategi pengiriman
public class JNEStrategy implements ShippingStrategy {
    @Override
    public double calculateCost(double weightKg, String destination) {
        return weightKg * 15_000 + (destination.contains("Luar Jawa") ? 10_000 : 0);
    }
    @Override public int estimateDeliveryDays(String dest) { return 3; }
    @Override public String getCourierName() { return "JNE Regular"; }
}

public class SiCepatStrategy implements ShippingStrategy {
    @Override
    public double calculateCost(double weightKg, String destination) {
        return weightKg * 12_000; // lebih murah
    }
    @Override public int estimateDeliveryDays(String dest) { return 2; }
    @Override public String getCourierName() { return "SiCepat Reguler"; }
}

public class SameDayDeliveryStrategy implements ShippingStrategy {
    @Override
    public double calculateCost(double weightKg, String destination) {
        return weightKg * 30_000 + 25_000; // premium
    }
    @Override public int estimateDeliveryDays(String dest) { return 0; }
    @Override public String getCourierName() { return "Same Day Delivery"; }
}

// Context: menggunakan strategy
public class ShoppingCart {
    private ShippingStrategy shippingStrategy;
    private List<CartItem> items = new ArrayList<>();

    public void setShippingStrategy(ShippingStrategy strategy) {
        this.shippingStrategy = strategy;
    }

    public ShippingQuote getShippingQuote(String destination) {
        double totalWeight = items.stream()
            .mapToDouble(i -> i.getWeightKg() * i.getQuantity()).sum();
        double cost = shippingStrategy.calculateCost(totalWeight, destination);
        int days    = shippingStrategy.estimateDeliveryDays(destination);
        return new ShippingQuote(shippingStrategy.getCourierName(), cost, days);
    }
}

