// Command interface
public interface Command {
    void execute();
    void undo();
    String getDescription();
}

// Receiver
public class TextEditor {
    private StringBuilder content = new StringBuilder();
    public void insertText(int pos, String text) {
        content.insert(pos, text);
    }
    public void deleteText(int pos, int length) {
        content.delete(pos, pos + length);
    }
    public String getContent() { return content.toString(); }
}

// Concrete Commands
public class InsertCommand implements Command {
    private final TextEditor editor;
    private final int position;
    private final String text;

    public InsertCommand(TextEditor editor, int position, String text) {
        this.editor   = editor;
        this.position = position;
        this.text     = text;
    }
    @Override public void execute() { editor.insertText(position, text); }
    @Override public void undo()    { editor.deleteText(position, text.length()); }
    @Override public String getDescription() { return "Insert '" + text + "' at " + position; }
}

// Invoker dengan undo/redo history
public class CommandHistory {
    private final Deque<Command> history = new ArrayDeque<>();
    private final Deque<Command> redoStack = new ArrayDeque<>();

    public void execute(Command cmd) {
        cmd.execute();
        history.push(cmd);
        redoStack.clear(); // redo tidak valid setelah command baru
        System.out.println("Executed: " + cmd.getDescription());
    }

    public void undo() {
        if (history.isEmpty()) { System.out.println("Tidak ada yang bisa di-undo"); return; }
        Command cmd = history.pop();
        cmd.undo();
        redoStack.push(cmd);
        System.out.println("Undo: " + cmd.getDescription());
    }

    public void redo() {
        if (redoStack.isEmpty()) { System.out.println("Tidak ada yang bisa di-redo"); return; }
        Command cmd = redoStack.pop();
        cmd.execute();
        history.push(cmd);
        System.out.println("Redo: " + cmd.getDescription());
    }
}

// Penggunaan
TextEditor editor   = new TextEditor();
CommandHistory hist = new CommandHistory();

hist.execute(new InsertCommand(editor, 0, "Halo"));
hist.execute(new InsertCommand(editor, 4, " Dunia"));
System.out.println(editor.getContent()); // "Halo Dunia"
hist.undo();
System.out.println(editor.getContent()); // "Halo"
hist.redo();
System.out.println(editor.getContent()); // "Halo Dunia"

// Abstract class dengan template method
public abstract class ReportGenerator {

    // Template method — urutan langkah sudah ditentukan
    public final Report generateReport(ReportRequest request) {
        validateRequest(request);
        List<Object> rawData = fetchData(request);
        List<Object> processedData = processData(rawData);
        formatData(processedData);
        Report report = buildReport(processedData, request);
        sendReport(report, request.getRecipients());
        return report;
    }

    // Langkah yang sama untuk semua jenis laporan
    private void validateRequest(ReportRequest req) {
        if (req.getStartDate().isAfter(req.getEndDate()))
            throw new IllegalArgumentException("Tanggal tidak valid");
        System.out.println("Validasi request berhasil");
    }

    // Hook method — boleh di-override, ada default
    protected void sendReport(Report report, List<String> recipients) {
        System.out.println("Mengirim laporan ke: " + recipients);
    }

    // Abstract methods — WAJIB diimplementasi subclass
    protected abstract List<Object> fetchData(ReportRequest request);
    protected abstract List<Object> processData(List<Object> rawData);
    protected abstract void formatData(List<Object> data);
    protected abstract Report buildReport(List<Object> data, ReportRequest req);
}

