// State interface
public interface OrderState {
    void processPayment(OrderContext context);
    void ship(OrderContext context);
    void deliver(OrderContext context);
    void cancel(OrderContext context);
    String getStateName();
}

// Context
public class OrderContext {
    private OrderState currentState;
    private String orderId;

    public OrderContext(String orderId) {
        this.orderId      = orderId;
        this.currentState = new PendingState(); // state awal
    }

    public void setState(OrderState state) {
        System.out.println("State berubah: " + currentState.getStateName()
                           + " -> " + state.getStateName());
        this.currentState = state;
    }

    // Delegasikan aksi ke state saat ini
    public void processPayment() { currentState.processPayment(this); }
    public void ship()           { currentState.ship(this); }
    public void deliver()        { currentState.deliver(this); }
    public void cancel()         { currentState.cancel(this); }
}

// Concrete States
public class PendingState implements OrderState {
    @Override public void processPayment(OrderContext ctx) {
        System.out.println("Pembayaran diproses...");
        ctx.setState(new PaidState());
    }
    @Override public void ship(OrderContext ctx) {
        System.out.println("ERROR: Pesanan belum dibayar!");
    }
    @Override public void deliver(OrderContext ctx) {
        System.out.println("ERROR: Pesanan belum dikirim!");
    }
    @Override public void cancel(OrderContext ctx) {
        System.out.println("Pesanan dibatalkan dari status pending");
        ctx.setState(new CancelledState());
    }
    @Override public String getStateName() { return "PENDING"; }
}

public class PaidState implements OrderState {
    @Override public void processPayment(OrderContext ctx) {
        System.out.println("ERROR: Sudah dibayar!");
    }
    @Override public void ship(OrderContext ctx) {
        System.out.println("Pesanan dikirim ke kurir");
        ctx.setState(new ShippedState());
    }
    @Override public void cancel(OrderContext ctx) {
        System.out.println("Pesanan dibatalkan, refund diproses");
        ctx.setState(new CancelledState());
    }
    @Override public void deliver(OrderContext ctx) {
        System.out.println("ERROR: Belum dikirim!");
    }
    @Override public String getStateName() { return "PAID"; }
}

