// Base exception
public class ApplicationException extends RuntimeException {
    private final String errorCode;
    public ApplicationException(String errorCode, String message) {
        super(message);
        this.errorCode = errorCode;
    }
}

public class ResourceNotFoundException extends ApplicationException {
    public ResourceNotFoundException(String resource, Long id) {
        super("RESOURCE_NOT_FOUND", resource + " dengan ID " + id + " tidak ditemukan");
    }
}

public class BusinessException extends ApplicationException {
    public BusinessException(String message) {
        super("BUSINESS_ERROR", message);
    }
}

public record ErrorResponse(
    String errorCode,
    String message,
    LocalDateTime timestamp,
    String path,
    Map<String, String> validationErrors
) {
    public static ErrorResponse of(String code, String msg, String path) {
        return new ErrorResponse(code, msg, LocalDateTime.now(), path, null);
    }
}

@RestControllerAdvice @Slf4j
public class GlobalExceptionHandler {

    @ExceptionHandler(ResourceNotFoundException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public ErrorResponse handleNotFound(ResourceNotFoundException ex,
                                        HttpServletRequest req) {
        log.warn("Resource not found: {}", ex.getMessage());
        return ErrorResponse.of(ex.getErrorCode(), ex.getMessage(), req.getRequestURI());
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public ErrorResponse handleValidation(MethodArgumentNotValidException ex,
                                          HttpServletRequest req) {
        Map<String, String> errors = new HashMap<>();
        ex.getBindingResult().getFieldErrors()
            .forEach(e -> errors.put(e.getField(), e.getDefaultMessage()));
        return new ErrorResponse("VALIDATION_ERROR", "Request tidak valid",
                                 LocalDateTime.now(), req.getRequestURI(), errors);
    }

    @ExceptionHandler(Exception.class)
    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    public ErrorResponse handleGeneric(Exception ex, HttpServletRequest req) {
        log.error("Unexpected error", ex);
        return ErrorResponse.of("INTERNAL_ERROR",
            "Terjadi kesalahan internal.", req.getRequestURI());
    }
}

