redis.opsForList().rightPush("antrian", tugas);

// Set — unik
redis.opsForSet().add("online", "user:1", "user:2");

// ZSet — leaderboard (skor)
redis.opsForZSet().add("ranking", "user:1", 100);

// Hash — objek field-value
redis.opsForHash().put("hotel:1", "nama", "Grand Hyatt");

