@RestController
@RequestMapping("/api/files")
public class FileController {

    private final FileStorageService storage;

    @PostMapping(value = "/upload", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<FileResponse> upload(@RequestParam("file") MultipartFile file) {

        // Validasi — SANGAT penting untuk keamanan
        if (file.isEmpty())
            throw new IllegalArgumentException("File kosong");
        if (file.getSize() > 5 * 1024 * 1024)   // maks 5 MB
            throw new IllegalArgumentException("File terlalu besar");

        String contentType = file.getContentType();
        if (!List.of("image/jpeg", "image/png", "application/pdf").contains(contentType))
            throw new IllegalArgumentException("Tipe file tidak diizinkan");

        String namaTersimpan = storage.simpan(file);
        return ResponseEntity.ok(new FileResponse(namaTersimpan, file.getSize()));
    }

    // Upload banyak file
    @PostMapping(value = "/upload-multi", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public List<FileResponse> uploadMulti(@RequestParam("files") MultipartFile[] files) {
        return Arrays.stream(files).map(f ->
            new FileResponse(storage.simpan(f), f.getSize())).toList();
    }
}

@Service
public class FileStorageService {
    private final Path root = Paths.get("uploads");

    public String simpan(MultipartFile file) {
        try {
            // Bersihkan nama file — cegah serangan "../../etc/passwd"
            String asli = StringUtils.cleanPath(file.getOriginalFilename());
            if (asli.contains(".."))
                throw new IllegalArgumentException("Nama file tidak valid");

            String namaUnik = UUID.randomUUID() + "_" + asli;  // hindari tabrakan nama
            Files.createDirectories(root);
            Files.copy(file.getInputStream(), root.resolve(namaUnik),
                       StandardCopyOption.REPLACE_EXISTING);
            return namaUnik;
        } catch (IOException e) {
            throw new RuntimeException("Gagal menyimpan file", e);
        }
    }
}

@GetMapping("/download/{nama}")
public ResponseEntity<Resource> download(@PathVariable String nama) throws IOException {
    Path file = Paths.get("uploads").resolve(nama);
    Resource resource = new UrlResource(file.toUri());
    if (!resource.exists()) return ResponseEntity.notFound().build();

    return ResponseEntity.ok()
        .header(HttpHeaders.CONTENT_DISPOSITION, "attachment; filename=\"" + nama + "\"")
        .contentType(MediaType.APPLICATION_OCTET_STREAM)
        .body(resource);
}

@Service
public class JwtService {
    @Value("${app.jwt.secret}")        private String jwtSecret;
    @Value("${app.jwt.expiration-ms}") private long   expirationMs;

    public String generateToken(UserDetails user) {
        return Jwts.builder()
            .subject(user.getUsername())
            .issuedAt(new Date())
            .expiration(new Date(System.currentTimeMillis() + expirationMs))
            .signWith(getSigningKey())
            .compact();
    }

    public boolean isTokenValid(String token, UserDetails user) {
        String username = extractUsername(token);
        return username.equals(user.getUsername()) && !isTokenExpired(token);
    }

    private SecretKey getSigningKey() {
        return Keys.hmacShaKeyFor(Decoders.BASE64.decode(jwtSecret));
    }
}

