        ProductResponse response = productService.create(req);

        // Then
        assertNotNull(response);
        assertEquals("Laptop", response.name());
        verify(productRepository).save(any(Product.class));
    }

    @Test
    void shouldThrowWhenNameExists() {
        when(productRepository.existsByName("Laptop")).thenReturn(true);
        assertThrows(BusinessException.class, () -> productService.create(req));
        verify(productRepository, never()).save(any()); // save tidak boleh dipanggil
    }
}

