@Transactional(readOnly = true)
public Page<ContactResponse> search(User user, SearchContactRequest request) {
    Specification<Contact> spec = (root, query, builder) -> {
        List<Predicate> predicates = new ArrayList<>();
        predicates.add(builder.equal(root.get("user"), user));
        if (Objects.nonNull(request.getName())) {
            predicates.add(builder.or(
                builder.like(root.get("firstName"), "%"+request.getName()+"%"),
                builder.like(root.get("lastName"), "%"+request.getName()+"%")));
        }
        if (Objects.nonNull(request.getEmail()))
            predicates.add(builder.like(root.get("email"), "%"+request.getEmail()+"%"));
        if (Objects.nonNull(request.getPhone()))
            predicates.add(builder.like(root.get("phone"), "%"+request.getPhone()+"%"));
        return query.where(predicates.toArray(new Predicate[]{})).getRestriction();
    };
    Pageable pageable = PageRequest.of(request.getPage(), request.getSize());
    Page<Contact> contacts = contactRepository.findAll(spec, pageable);
    List<ContactResponse> responses = contacts.getContent().stream()
        .map(this::toContactResponse).toList();
    return new PageImpl<>(responses, pageable, contacts.getTotalElements());
}

