@Service
public class TransferService {

    @Transactional
    public TransferResult transfer(TransferCommand cmd) {
        // Pessimistic lock: kunci baris rekening selama transaksi
        Rekening dari = repo.findByIdForUpdate(cmd.dariId())
                            .orElseThrow(() -> new RekeningNotFoundException(cmd.dariId()));
        Rekening ke   = repo.findByIdForUpdate(cmd.keId())
                            .orElseThrow(() -> new RekeningNotFoundException(cmd.keId()));

        validasiLimitHarian(dari, cmd.jumlah());      // cek limit
        cekFraud(cmd);                                 // skrining anti-fraud

        if (dari.getSaldo().compareTo(cmd.jumlah()) < 0)
            throw new SaldoTidakCukupException("Saldo tidak mencukupi");

        dari.debit(cmd.jumlah());
        ke.kredit(cmd.jumlah());

        var trx = mutasiRepo.save(Mutasi.transfer(dari, ke, cmd.jumlah(), cmd.referenceNo()));
        auditLog.catat("TRANSFER", cmd, trx.getId());  // jejak audit immutable

        return TransferResult.sukses(trx.getReferenceNo());
    }
}

