public static long fibBottomUp(int n) {
    if (n <= 1) return n;

    long prev2 = 0, prev1 = 1;

    for (int i = 2; i <= n; i++) {
        long curr = prev1 + prev2; // hitung dari bawah ke atas
        prev2 = prev1;
        prev1 = curr;
    }
    return prev1;
}
