@Service
public class TransferService {

    @Transactional   // jika error di tengah, SEMUA dibatalkan
    public void transfer(Long dariId, Long keId, BigDecimal jumlah) {
        Rekening dari = repo.findById(dariId).orElseThrow();
        Rekening ke   = repo.findById(keId).orElseThrow();

        if (dari.getSaldo().compareTo(jumlah) < 0)
            throw new SaldoTidakCukupException("Saldo kurang");

        dari.setSaldo(dari.getSaldo().subtract(jumlah));
        ke.setSaldo(ke.getSaldo().add(jumlah));
        // Jika listrik mati di sini → rollback otomatis, uang tidak hilang
        repo.save(dari);
        repo.save(ke);
    }
}

