    public ResponseEntity<ErrorResponse> handleValidasi(MethodArgumentNotValidException e) {
        Map<String, String> errors = new HashMap<>();
        e.getBindingResult().getFieldErrors().forEach(err ->
            errors.put(err.getField(), err.getDefaultMessage()));
        return ResponseEntity.badRequest()
            .body(new ErrorResponse("VALIDATION_ERROR", errors));
    }

    @ExceptionHandler(SaldoTidakCukupException.class)
    public ResponseEntity<ErrorResponse> handleSaldo(SaldoTidakCukupException e) {
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
            .body(new ErrorResponse("INSUFFICIENT_BALANCE", e.getMessage()));
    }
}

