@Aspect @Component @Slf4j
public class LoggingAspect {

    // Around — wrap seluruh eksekusi method
    @Around("execution(* com.myapp.service.*.*(..))")
    public Object measurePerformance(ProceedingJoinPoint joinPoint) throws Throwable {
        long start = System.currentTimeMillis();
        try {
            Object result = joinPoint.proceed(); // eksekusi method asli
            log.info("Method {} selesai dalam {}ms",
                joinPoint.getSignature().getName(),
                System.currentTimeMillis() - start);
            return result;
        } catch (Exception e) {
            log.error("Method {} gagal: {}",
                joinPoint.getSignature().getName(), e.getMessage());
            throw e;
        }
    }
}

// 1. Buat annotation
@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
public @interface Auditable { String action(); }

// 2. Buat Aspect
@Aspect @Component @RequiredArgsConstructor
public class AuditAspect {
    private final AuditLogRepository auditLogRepository;

    @Around("@annotation(auditable)")
    public Object audit(ProceedingJoinPoint jp, Auditable auditable) throws Throwable {
        String user = SecurityContextHolder.getContext()
                          .getAuthentication().getName();
        try {
            Object result = jp.proceed();
            auditLogRepository.save(
                new AuditLog(user, auditable.action(), "SUCCESS"));
            return result;
        } catch (Exception e) {
            auditLogRepository.save(
                new AuditLog(user, auditable.action(), "FAILED"));
            throw e;
        }
    }
}

